package com.andye.warmod.warhead.client;

import com.andye.warmod.diagnostics.client.ClientPerformanceTelemetry;
import com.andye.warmod.warhead.WarheadPayloadType;import com.andye.warmod.warhead.WarheadEffectProfile;import com.andye.warmod.warhead.client.render.BlastCloudFlowRole;import com.andye.warmod.warhead.client.render.BlastCloudLobe;import com.andye.warmod.warhead.client.render.FireballLobe;import com.andye.warmod.warhead.network.ClientboundWarheadImpactPayload;import java.util.ArrayList;import java.util.List;import java.util.SplittableRandom;import java.util.UUID;import net.minecraft.util.Mth;import net.minecraft.world.phys.Vec3;
public final class ImpactVisualState {
	private final UUID warheadId;private final Vec3 impactPosition,ambientWind;private final long impactGameTime,visualSeed;private final float visualScale;private final WarheadPayloadType payloadType;private WarheadEffectProfile effectProfile;private final WarheadClientVisualProfile profile;private final TerrainRingSampler terrainSampler;private final TerrainShockfrontField terrainShockfrontField;private final List<FireballLobe> fireballLobes;private final List<BlastCloudLobe> blastCloudLobes;private boolean initialBurstEmitted,secondaryBurstEmitted;private long lastContinuousParticleTick=Long.MIN_VALUE;private int emittedParticleCount;
	public ImpactVisualState(final UUID id,final Vec3 position,final long time,final long seed,final WarheadPayloadType payloadType,final float scale){this(id,position,time,seed,payloadType,scale,Vec3.ZERO,null);}
	private ImpactVisualState(final UUID id,final Vec3 position,final long time,
		final long seed,final WarheadPayloadType payloadType,final float scale,
		final Vec3 ambientWind,final TerrainShockfrontField preparedField){
		this.warheadId=id;this.impactPosition=position;
		this.ambientWind=ambientWind==null||!ambientWind.isFinite()?Vec3.ZERO:ambientWind;
		this.impactGameTime=time;this.visualSeed=seed;this.payloadType=payloadType;
		this.effectProfile=WarheadEffectProfile.CONVENTIONAL;this.visualScale=scale;
		this.profile=WarheadClientVisualProfiles.get(payloadType,seed);
		this.terrainSampler=new TerrainRingSampler(position,seed);
		this.terrainShockfrontField=preparedField==null
			?new TerrainShockfrontField(position,seed):preparedField;
		long fireballStarted=System.nanoTime();
		this.fireballLobes=createFireballLobes(seed,profile);
		ClientPerformanceTelemetry.recordFireballLobePreparationNanos(
			Math.max(0L,System.nanoTime()-fireballStarted));
		long cloudStarted=System.nanoTime();
		this.blastCloudLobes=createSmokeLobes(seed,profile);
		ClientPerformanceTelemetry.recordCloudLobePreparationNanos(
			Math.max(0L,System.nanoTime()-cloudStarted));
	}
	public static ImpactVisualState fromPayload(final ClientboundWarheadImpactPayload p){return fromPayload(p,null);}
	public static ImpactVisualState fromPayload(final ClientboundWarheadImpactPayload p,final TerrainShockfrontField preparedField){ImpactVisualState state=new ImpactVisualState(p.warheadId(),new Vec3(p.impactX(),p.impactY(),p.impactZ()),p.impactGameTime(),p.visualSeed(),p.payloadType(),p.impactVisualScale(),new Vec3(p.windX(),0.0,p.windZ()),preparedField);state.effectProfile=p.effectProfile();return state;}
	public WarheadEffectProfile effectProfile(){return effectProfile;}public UUID warheadId(){return warheadId;}public Vec3 impactPosition(){return impactPosition;}public Vec3 ambientWind(){return ambientWind;}public long impactGameTime(){return impactGameTime;}public long visualSeed(){return visualSeed;}public float visualScale(){return visualScale;}public WarheadPayloadType payloadType(){return payloadType;}public WarheadClientVisualProfile profile(){return profile;}public TerrainRingSampler terrainSampler(){return terrainSampler;}public TerrainShockfrontField terrainShockfrontField(){return terrainShockfrontField;}public List<FireballLobe> fireballLobes(){return fireballLobes;}public List<BlastCloudLobe> blastCloudLobes(){return blastCloudLobes;}
	public double ageTicks(final long time,final double partial){return Math.max(0,time-impactGameTime)+Math.max(0,Math.min(1,partial));}public boolean isExpired(final long time,final double partial){double age=ageTicks(time,partial);return !Double.isFinite(age)||age>=profile.totalImpactLifetimeTicks();}boolean initialBurstEmitted(){return initialBurstEmitted;}void markInitialBurstEmitted(){initialBurstEmitted=true;}boolean secondaryBurstEmitted(){return secondaryBurstEmitted;}void markSecondaryBurstEmitted(){secondaryBurstEmitted=true;}long lastContinuousParticleTick(){return lastContinuousParticleTick;}void markContinuousParticleTick(final long t){lastContinuousParticleTick=t;}int emittedParticleCount(){return emittedParticleCount;}void recordParticleEmission(){emittedParticleCount++;}
	private static List<FireballLobe> createFireballLobes(final long seed,final WarheadClientVisualProfile p){SplittableRandom random=new SplittableRandom(seed^0x464952454C4F4245L);int count=p.nearFireballLobes();List<FireballLobe> lobes=new ArrayList<>(count);boolean nuclear=p.payloadType()==WarheadPayloadType.NUCLEAR;for(int index=0;index<count;index++){double fraction=index/(double)count;int band=nuclear?(fraction<.55?0:fraction<.85?1:2):(fraction<.45?0:fraction<.80?1:2);double angle=random.nextDouble(0,Math.PI*2),radialFactor;if(nuclear)radialFactor=band==0?Math.pow(random.nextDouble(),1.65)*.42:band==1?random.nextDouble(.30,.74):random.nextDouble(.66,1.0);else radialFactor=band==0?Math.sqrt(random.nextDouble())*.42:band==1?random.nextDouble(.35,.72):random.nextDouble(.68,1.0);double width=nuclear?p.fireballWidth():60,height=nuclear?p.fireballHeight():84;double radial=radialFactor*width*.5;double verticalFactor=nuclear?Math.pow(random.nextDouble(),1.28):Math.pow(random.nextDouble(),.82);double y=verticalFactor*height;Vec3 offset=new Vec3(Math.cos(angle)*radial,y,Math.sin(angle)*radial);double radius=nuclear?(band==0?random.nextDouble(11,19):band==1?random.nextDouble(10,18):random.nextDouble(9,16)):random.nextDouble(3,6.5);float opacity=nuclear?(band==0?1.10F:band==1?1.03F:.96F):1.0F;double angular=(random.nextBoolean()?1:-1)*random.nextDouble(nuclear?.001:.002,nuclear?.004:.006);double vertical=random.nextDouble(nuclear?.02:.01,nuclear?.06:.035);lobes.add(new FireballLobe(offset,random.nextDouble(0,nuclear?5:3),radius,random.nextDouble(.85,1.18),random.nextDouble(.45,1.05),random.nextDouble(.4,nuclear?6:3.2),random.nextDouble(0,Math.PI*2),random.nextDouble(0,8),random.nextDouble(.8,1.25),random.nextDouble(0,Math.PI*2),random.nextDouble(nuclear?.06:.09,nuclear?.11:.16),angular,vertical,opacity));}return List.copyOf(lobes);}
	private static List<BlastCloudLobe> createSmokeLobes(final long seed,final WarheadClientVisualProfile p){SplittableRandom r=new SplittableRandom(seed^0x424C415354434C44L);int count=p.nearSmokeLobes();List<BlastCloudLobe> list=new ArrayList<>(count);boolean nuclear=p.payloadType()==WarheadPayloadType.NUCLEAR;int stemEnd=nuclear?(int)Math.round(count*.40):(int)Math.round(count*.50);int coreEnd=nuclear?(int)Math.round(count*.65):(int)Math.round(count*.80);for(int i=0;i<count;i++){BlastCloudFlowRole role=i<stemEnd?BlastCloudFlowRole.STEM:i<coreEnd?BlastCloudFlowRole.CAP_CORE:BlastCloudFlowRole.CAP_ROLLING_RIM;double angle=r.nextDouble(0,Math.PI*2),finalRadial,finalY,originRadial,originY,spawn,growth;if(nuclear&&role==BlastCloudFlowRole.STEM){finalY=r.nextDouble(2,p.maximumCloudHeight()*.72);finalRadial=r.nextDouble(.4,p.smokeStemWidth()*.50);originY=Math.min(16,finalY*.10);originRadial=finalRadial*r.nextDouble(.05,.15);double heightFraction=finalY/p.maximumCloudHeight();spawn=Math.max(p.smokeStartTick(),p.smokeStartTick()+heightFraction*230+r.nextDouble(-10,10));growth=r.nextDouble(90,180);}else if(nuclear){double minimum=role==BlastCloudFlowRole.CAP_ROLLING_RIM?.34:.08;finalRadial=r.nextDouble(p.smokeCapWidth()*minimum,p.smokeCapWidth()*.50);finalY=r.nextDouble(p.maximumCloudHeight()*(role==BlastCloudFlowRole.CAP_ROLLING_RIM?.66:.70),p.maximumCloudHeight()*.92);double radialFraction=finalRadial/(p.smokeCapWidth()*.50);originY=p.maximumCloudHeight()*r.nextDouble(.54,.64);originRadial=finalRadial*r.nextDouble(0,.08);double phase=r.nextDouble(0,Math.PI*2);spawn=Mth.clamp(110+radialFraction*260+Math.sin(phase)*9+r.nextDouble(-10,10),100,390);growth=r.nextDouble(150,280);angle+=phase*.025;}else{boolean cap=role!=BlastCloudFlowRole.STEM;finalRadial=cap?r.nextDouble(2.5,11):r.nextDouble(.4,4.5);finalY=cap?r.nextDouble(10,28):r.nextDouble(0,20);originRadial=finalRadial*.15;originY=Math.min(4,finalY*.2);spawn=p.smokeStartTick()+r.nextDouble(2,55);growth=r.nextDouble(70,150);}Vec3 origin=new Vec3(Math.cos(angle)*originRadial,originY,Math.sin(angle)*originRadial),target=new Vec3(Math.cos(angle)*finalRadial,finalY,Math.sin(angle)*finalRadial);boolean core=i%3!=0;int red=core?r.nextInt(18,43):r.nextInt(55,101),green=core?r.nextInt(20,47):r.nextInt(60,106),blue=core?r.nextInt(24,55):r.nextInt(68,116);float opacity=(float)(core?r.nextDouble(nuclear?.72:.46,nuclear?.88:.63):r.nextDouble(nuclear?.48:.28,nuclear?.70:.45));double radius=nuclear?(role==BlastCloudFlowRole.STEM?r.nextDouble(8,16):r.nextDouble(14,27)):(role==BlastCloudFlowRole.STEM?r.nextDouble(2.5,4.3):r.nextDouble(3,5.5));double circulation=role==BlastCloudFlowRole.CAP_ROLLING_RIM?-r.nextDouble(.005,.012):0;list.add(new BlastCloudLobe(origin,target,spawn,growth,radius,r.nextDouble(.8,1.2),r.nextDouble(1,nuclear?18:7),angle,r.nextDouble(0,Math.PI*2),role,r.nextDouble(0,Math.PI*2),circulation,r.nextDouble(.30,.47),r.nextDouble(.70,.88),r.nextDouble(0,Math.PI*2),red,green,blue,opacity));}return List.copyOf(list);}
}
